module benchmark/solution

import std/string (chars)

pure func toRomanGo(n: int, table: [(int, string)]) -> string =
  match table {
    [] => "",
    (v, s) :: rest =>
      if n >= v then "${s}${toRomanGo(n - v, table)}" else toRomanGo(n, rest)
  }

export pure func toRoman(n: int) -> string =
  toRomanGo(n, [(1000, "M"), (900, "CM"), (500, "D"), (400, "CD"), (100, "C"), (90, "XC"),
                (50, "L"), (40, "XL"), (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")])

pure func charValue(c: string) -> int =
  match c {
    "I" => 1,
    "V" => 5,
    "X" => 10,
    "L" => 50,
    "C" => 100,
    "D" => 500,
    "M" => 1000,
    _ => 0
  }

pure func sumValues(vs: [int]) -> int =
  match vs {
    [] => 0,
    [v] => v,
    a :: b :: rest => if a < b then sumValues(b :: rest) - a else a + sumValues(b :: rest)
  }

export pure func fromRoman(s: string) -> int =
  sumValues(map(charValue, chars(s)))

pure func map(f: string -> int, xs: [string]) -> [int] =
  match xs {
    [] => [],
    x :: rest => f(x) :: map(f, rest)
  }

export pure func roundtrip(n: int) -> bool =
  fromRoman(toRoman(n)) == n

export pure func distinctEncoding(a: int, b: int) -> bool =
  a == b || toRoman(a) != toRoman(b)

export func main() -> () ! {IO} {
  println(toRoman(1994));
  println(toRoman(58));
  println(toRoman(3999));
  println(show(fromRoman("MCMXCIV")));
  println(show(fromRoman("LVIII")));
  println(show(roundtrip(2024)));
  println(show(distinctEncoding(4, 6)))
}

